head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.ETN_MBR_INFO_TP_CD = "3";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.flagVal;
scwin.TR_JOB;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.setDataHeader();
        scwin.enableBtnSend(false);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_5_OnLoadCompleted
 * @description dts_List_5 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_5_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dts_List_5_OnLoadError
 * @description dts_List_5 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_5_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_5);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.dts_List_5_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lce.fn_alertMsg('S');
        await scwin.listSync();
        scwin.disableItem();
        scwin.enableBtnSend(false);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert("Error Code : " + trs_Save.ErrorCode + "\n" + "Error Message : " + trs_Save.ErrorMsg + "\n");
        $c.lce.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_SDate_5_2_onclick
 * @description btn_SDate_5_2 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_5_2_onclick = function() {
    try {
        popUpCalendar2(edt_SDate_5_2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08071.btn_SDate_5_2_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_5_1_onclick
 * @description btn_SDate_5_1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_5_1_onclick = function() {
    try {
        popUpCalendar2(edt_SDate_5_1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08071.btn_SDate_5_1_onclick" });
    }
};

/**
 * @method
 * @name grd_List_5_OnClick
 * @description grd_List_5 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_5_OnClick = function(row, colid) {
    try {
        scwin.setValue(row);
        scwin.enableBtnSend(true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08071.grd_List_5_OnClick" });
    }
};

/**
 * @method
 * @name btn_Close_5_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_5_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.btn_Close_5_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_5_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete_5_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.btn_Delete_5_onclick" });
    }
};

/**
 * @method
 * @name btn_Modify5_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify5_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.btn_Modify5_onclick" });
    }
};

/**
 * @method
 * @name btn_New_5_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_5_onclick = function() {
    try {
        scwin.TR_JOB = "I";
        scwin.enableItem();
        scwin.enableBtnSend(false);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08071.btn_New_5_onclick" });
    }
};

/**
 * @method
 * @name btn_Send_Mail_onclick
 * @description 「메일발송」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Send_Mail_onclick = async function() {
    try {
        await scwin.sendMail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.btn_Send_Mail_onclick" });
    }
};

/**
 * @method
 * @name trs_MailList_OnFail
 * @description Mail List On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_MailList_OnFail = async function() {
    try {
        const ErrorCount = trs_MailList.SrvErrCount("ACTION");
        if (ErrorCount > 0) {
            await $c.win.alert("전송 실패");
            await $c.win.alert(trs_MailList);
        } else {
            // 이건 성공임.
            await $c.win.alert("전송 성공");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.trs_MailList_OnFail" });
    }
};

/**
 * @method
 * @name trs_MailList_OnSuccess
 * @description Mail List On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_MailList_OnSuccess = async function() {
    try {
        await $c.win.alert("전송 성공");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08071.trs_MailList_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_MailList_OnLoadCompleted
 * @description dts_MailList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MailList_OnLoadCompleted = function(rowcount) {
    // alert('dts_MailList.OnLoadCompleted('+rowcount+')'+dts_MailList.NameString(1, "EMAIL") );

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    scwin.disableItem();
    url += "&ETN_MBR_INFO_TP_CD=" + scwin.ETN_MBR_INFO_TP_CD;
    url += "&SCREN_ID=" + "ULDSTF08071.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_List_5",
        action : "/etn/EtnStatMgt.do",
        ref : "",
        target : "dts_List_5=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /*
    url = "/etn/EtnStatMgt.do?method=listSendMailList";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MailList.DataID = encodeURI(url);
    dts_MailList.reset();
     */

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    // alert("INFO_RND : "+dts_List_5.NameString(dts_List_5.RowPosition, "INFO_RND"));
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.TR_JOB === "I") vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.TR_JOB === "U") vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;

    else if (scwin.TR_JOB === "D") vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    dts_Item.setCellData(1, "NOTI_TITLE", txb_NotiTitle_5.getValue());
    dts_Item.setCellData(1, "NOTI_CONTN", txa_NotiContn_5.getValue());
    dts_Item.setCellData(1, "STRT_DD", edt_SDate_5_1.getValue());
    dts_Item.setCellData(1, "END_DD", edt_SDate_5_2.getValue());
    dts_Item.setCellData(1, "INFO_RND", dts_List_5.getCellData(dts_List_5.getRowPosition(), "INFO_RND"));
    dts_Item.setCellData(1, "ETN_MBR_INFO_TP_CD", scwin.ETN_MBR_INFO_TP_CD);
    trs_Save.KeyName = "toinb_dataid4";

    // alert(dts_Item.Text);
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/etn/EtnStatMgt.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name sendMail
 * @description send Mail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendMail = async function() {
    if ($c.en.fn_CheckForm()) {
        const res = window.confirm("[메일]을 전송하시겠습니까?");
        if (res) {
            const NotiTitle = txb_NotiTitle_5.getValue();
            const NotiContn = txa_NotiContn_5.getValue();
            trs_MailList.KeyName = "toinb_dataid4";
            // [전환검토] trs_MailList.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     NotiTitle : NotiTitle,
            //     NotiContn : NotiContn,
            //     SCREN_ID : "ULDSTF08071.xml",
            //     SCREN_PROCES_TP_CD : SCREN_PROCS_TP_CD_02
            // };
            const sbmOptions = {
                id : "sbm_trs_MailList",
                action : "/etn/EtnStatMgt.do",
                ref : "dts_MailList",
                target : "trs_MailList=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setDataHeader
 * @description set Data Header 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataHeader = function() {
    dts_Item.removeAll();
    // dts_Item.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    // 껍데기만 만들고 사용자필드를 사용함
    dts_Item.insertRow();
};

/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {

};

/**
 * @method
 * @name setValue
 * @description set Value 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setValue = function(row) {
    if (row > 0) {
        // 그리드에서 선택시
        scwin.TR_JOB = "U";
        scwin.enableItem();
        txb_NotiTitle_5.setValue(dts_List_5.getCellData(Number(row), "NOTI_TITLE"));
        txa_NotiContn_5.setValue(dts_List_5.getCellData(Number(row), "NOTI_CONTN"));
        edt_SDate_5_1.setValue($c.ut.replaceAll(dts_List_5.getCellData(Number(row), "STRT_DD"), "-", ""));
        edt_SDate_5_2.setValue($c.ut.replaceAll(dts_List_5.getCellData(Number(row), "END_DD"), "-", ""));
    }
};

/**
 * @method
 * @name enableItem
 * @description enable Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.enableItem = function() {
    txb_NotiTitle_5.setValue("");
    txa_NotiContn_5.setValue("");
    edt_SDate_5_1.setValue("");
    edt_SDate_5_2.setValue("");
    btn_SDate_5_1.setDisabled(false);
    btn_SDate_5_2.setDisabled(false);
    edt_SDate_5_1.setReadOnly(false);
    edt_SDate_5_2.setReadOnly(false);
    txb_NotiTitle_5.setReadOnly(false);
    txa_NotiContn_5.setReadOnly(false);
    txb_NotiTitle_5.setStyle("backgroundcolor", "#ffffff");
    txa_NotiContn_5.style.background = "#ffffff";
    edt_SDate_5_1.setStyle("backgroundcolor", "#ffffff");
    edt_SDate_5_2.setStyle("backgroundcolor", "#ffffff");
};

/**
 * @method
 * @name disableItem
 * @description disable Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.disableItem = function() {
    txb_NotiTitle_5.setValue("");
    txa_NotiContn_5.setValue("");
    edt_SDate_5_1.setValue("");
    edt_SDate_5_2.setValue("");
    btn_SDate_5_1.setDisabled(true);
    btn_SDate_5_2.setDisabled(true);
    edt_SDate_5_1.setReadOnly(true);
    edt_SDate_5_2.setReadOnly(true);
    txb_NotiTitle_5.setReadOnly(true);
    txa_NotiContn_5.setReadOnly(true);
    txb_NotiTitle_5.setStyle("backgroundcolor", "#b9d4f7");
    txa_NotiContn_5.style.background = "#b9d4f7";
    edt_SDate_5_1.setStyle("backgroundcolor", "#b9d4f7");
    edt_SDate_5_2.setStyle("backgroundcolor", "#b9d4f7");
};

/**
 * @method
 * @name enableBtnSend
 * @description enable Btn Send 처리
 * @param {*} status status
 * @returns {void}
 * @hidden N
 */
scwin.enableBtnSend = function(status) {
    if (status) {
        btn_Send_Mail.setBackgroundImage("../img/btn_send_mail.gif");
        btn_Send_Mail.setDisabled(false);
    } else {
        btn_Send_Mail.setBackgroundImage("../img/btn_send_mail_dis.gif");
        btn_Send_Mail.setDisabled(true);
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_NotiTitle_5.getValue() === "") {
        await $c.win.alert("[제목]을 입력하세요.");
        txb_NotiTitle_5.focus();
        return false;
    }
    if (txa_NotiContn_5.getValue() === "") {
        await $c.win.alert("[내용]을 입력하세요.");
        txa_NotiContn_5.focus();
        return false;
    }
    if (!$c.lce.checkDdTm("DD", edt_SDate_5_1, "메시지 표시기간 시작", true)) return false;
    if (!$c.lce.checkDdTm("DD", edt_SDate_5_2, "메시지 표시기간 종료", true)) return false;
    if (edt_SDate_5_1.getValue() === "") {
        await $c.win.alert("[[메시지 표시기간 시작일]을 입력하세요.");
        edt_SDate_5_1.focus();
        return false;
    }
    if (edt_SDate_5_2.getValue() === "") {
        await $c.win.alert("[[메시지 표시기간 종료일]을 입력하세요.");
        edt_SDate_5_2.focus();
        return false;
    }
    if (edt_SDate_5_2.getValue() !== "" && (edt_SDate_5_1.getValue() > edt_SDate_5_2.getValue())) {
        await $c.win.alert("[메시지 표시기간 종료일]은 [메시지 표시기간 시작일]이후로 입력하세요.");
        edt_SDate_5_2.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "TR_JOB", scwin.TR_JOB);
        dts_Item.setCellData(1, "ETN_MBR_INFO_TP_CD", scwin.ETN_MBR_INFO_TP_CD);
        dts_Item.setCellData(1, "EMP_NO", js_id);
        await scwin.trs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    scwin.TR_JOB = "D";
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "TR_JOB", scwin.TR_JOB);
        dts_Item.setCellData(1, "ETN_MBR_INFO_TP_CD", scwin.ETN_MBR_INFO_TP_CD);
        await scwin.trs();
    }
};
